@Suite("Price parser")
struct PriceParserTests {
    struct PriceCase: Sendable, CustomTestStringConvertible {
        let text: String
        let fallback: String?
        let amount: String
        let currency: String
        var testDescription: String { text }
    }

    @Test(arguments: [
        PriceCase(text: "£12,950.00", fallback: nil, amount: "12950", currency: "GBP"),
        PriceCase(text: "US $4,250.00", fallback: nil, amount: "4250", currency: "USD"),
        PriceCase(text: "€ 2.300,00", fallback: nil, amount: "2300", currency: "EUR"),
        PriceCase(text: "CHF 8'900.–", fallback: nil, amount: "8900", currency: "CHF"),
        PriceCase(text: "3150.0", fallback: "GBP", amount: "3150", currency: "GBP"),
        PriceCase(text: "1.650", fallback: "EUR", amount: "1650", currency: "EUR"),
        PriceCase(text: "£3,150.00 GBP", fallback: nil, amount: "3150", currency: "GBP"),
        PriceCase(text: "12 950 €", fallback: nil, amount: "12950", currency: "EUR"),
        PriceCase(text: "From £1,000 - £2,000", fallback: nil, amount: "1000", currency: "GBP"),
        PriceCase(text: "£949.99", fallback: nil, amount: "949.99", currency: "GBP"),
    ])
    func parses(_ c: PriceCase) {
        #expect(PriceParser.parse(c.text, fallbackCurrency: c.fallback) == Money(amount: Decimal(string: c.amount)!, currency: c.currency))
    }

    @Test func needsACurrency() {
        #expect(PriceParser.parse("3150") == nil)
    }

    @Test func pence() {
        #expect(Money(amount: Decimal(string: "949.99")!, currency: "GBP").pence == 94999)
        #expect(PriceFormatter.pence(fromEditing: "12,950") == 1_295_000)
        #expect(PriceFormatter.editingText(pence: 94999) == "949.99")
    }
}

@Suite("Reference detector")
struct ReferenceDetectorTests {
    @Test(arguments: [
        ("Rolex Submariner Date 126610LN 41mm Black Dial 2021", "126610LN"),
        ("Grand Seiko SBGA211 Snowflake", "SBGA211"),
        ("Patek Philippe Nautilus 5711/1A-010", "5711/1A-010"),
        ("Rolex Explorer Ref. 1016 from 1968", "1016"),
        ("IWC Pilot's Mark XVIII IW327001", "IW327001"),
    ])
    func finds(text: String, expected: String) {
        #expect(ReferenceDetector.best(in: text) == expected)
    }

    @Test(arguments: ["Omega Seamaster Diver 300M", "Rolex 2023 Datejust 41 mm", "Seiko 5 Sports £249"])
    func ignores(text: String) {
        #expect(ReferenceDetector.best(in: text) == nil)
    }
}

@Suite("Specs in sentences")
struct SentenceSpecTests {
    private func read(_ text: String) -> [String: String] {
        Dictionary(uniqueKeysWithValues: SpecNormalizer.specs(from: SpecTable([]), title: "", text: text).map { ($0.label, $0.value) })
    }

    @Test func numberBeforeTheLabel() {
        let specs = read("36mm case width8.8mm case thickness + 1.6mm dome crystal44mm case length / lug-to-lug20mm lug width tapers to 16mm at clasp")
        #expect(specs["Case size"] == "36 mm")
        #expect(specs["Thickness"] == "8.8 mm")
    }

    @Test func labelBeforeTheNumber() {
        let specs = read("A case diameter of 41 mm and a case thickness of 12.5mm")
        #expect(specs["Case size"] == "41 mm")
        #expect(specs["Thickness"] == "12.5 mm")
    }

    @Test func otherPartsAreNotTheCase() {
        #expect(read("20mm lug width tapers to 16mm at clasp")["Case size"] == nil)
        #expect(read("Lug width: 20mm")["Case size"] == nil)
        #expect(read("The bracelet tapers from 20mm at the case to 16mm at the clasp")["Case size"] == nil)
        #expect(read("44mm case length")["Case size"] == nil)
        #expect(read("Sapphire crystal thickness 1.6mm")["Thickness"] == nil)
    }
}

@Suite("Page suggestions")
struct PageSuggestionTests {
    @Test func twoCaseSizesAreLeftToChoose() {
        let reading = SpecNormalizer.reading(from: SpecTable([]), title: "", text: "Available as a 38mm case or a 41mm case")
        #expect(!reading.specs.contains { $0.label == "Case size" })
        #expect(reading.suggestions["Case size"] == ["38 mm", "41 mm"])
    }

    @Test func oneSizeSaidTwiceIsCertain() {
        let reading = SpecNormalizer.reading(from: SpecTable([]), title: "", text: "36mm case width\nThe 36mm case suits most wrists")
        #expect(reading.specs.first { $0.label == "Case size" }?.value == "36 mm")
        #expect(reading.suggestions.isEmpty)
    }

    @Test func aHeadingIsNotACalibre() {
        let table = SpecTable([["Calibre", "At heart"], ["Movement", "Calibre at heart"]])
        let reading = SpecNormalizer.reading(from: table, title: "", calibres: ["Jaeger-LeCoultre Caliber 868", "Calibre 868 in detail", "Caliber 925"])
        #expect(!reading.specs.contains { $0.label == "Calibre" || $0.label == "Movement" })
        #expect(reading.suggestions["Calibre"] == ["Calibre 868", "Calibre 925"])
    }

    @Test func oneNamedCalibreFillsTheField() {
        let reading = SpecNormalizer.reading(from: SpecTable([]), title: "", calibres: ["Jaeger-LeCoultre Caliber 925"])
        #expect(reading.specs.first { $0.label == "Calibre" }?.value == "Calibre 925")
    }

    @Test func labelsBrandsUseForTheSameSpec() {
        let table = SpecTable([["Dimension", "Ø 39.00 mm"], ["Lug distance", "20 mm"], ["Lug‑to‑lug", "47.50 mm"], ["Waterproofness", "Waterproof to 200 m"], ["Power Reserve", "65-hour power reserve"], ["Total product weight (approx.)", "138 g"], ["Lugs", "20mm lug width"]])
        let specs = Dictionary(uniqueKeysWithValues: SpecNormalizer.specs(from: table, title: "").map { ($0.label, $0.value) })
        #expect(specs["Case size"] == "39.00 mm")
        #expect(specs["Lug width"] == "20 mm")
        #expect(specs["Lug to lug"] == "47.50 mm")
        #expect(specs["Water resistance"] == "Waterproof to 200 m")
        #expect(specs["Power reserve"] == "65-hour power reserve")
        #expect(specs["Weight"] == "138 g")
    }

    @Test func modelNamesReadNaturally() {
        #expect(ListingInterpreter.readable("SPIRIT PILOT") == "Spirit Pilot")
        #expect(ListingInterpreter.readable("Master Ultra Thin MOON") == "Master Ultra Thin Moon")
        #expect(ListingInterpreter.readable("GMT-MASTER II") == "GMT-Master II")
        #expect(ListingInterpreter.readable("C60 Trident Pro 300") == "C60 Trident Pro 300")
    }

    @Test func preOwnedDetails() {
        let specs = Dictionary(uniqueKeysWithValues: SpecNormalizer.specs(from: SpecTable([]), title: "", text: "Full set, year 2019, in excellent condition").map { ($0.label, $0.value) })
        #expect(specs["Year"] == "2019")
        #expect(specs["Condition"] == "Excellent")
        #expect(specs["Box"] == "Yes")
        #expect(specs["Papers"] == "Yes")
    }

    @Test func modelAnswersMustBeOnThePage() {
        #expect(FoundationModelsFallback.isGrounded("IWC", in: "The IWC Portugieser"))
        #expect(!FoundationModelsFallback.isGrounded("IWC", in: "The Portugieser"))
        #expect(FoundationModelsFallback.statesAmount(12950, in: "Price £12,950.00"))
        #expect(!FoundationModelsFallback.statesAmount(12950, in: "Price £1,295"))
    }
}

@Suite("Image picking")
struct ImagePickingTests {
    private func draft(_ json: String) throws -> ListingDraft {
        ListingInterpreter.interpret(try #require(PageSnapshot.decode(json)))
    }

    @Test func galleryPhotosComeFirstAndAlone() throws {
        let d = try draft("""
            {"url":"https://shop.example/watch.html","images":[
              {"src":"https://shop.example/images/C60-ABC/1.jpg","w":0,"h":0,"g":true},
              {"src":"https://shop.example/images/C60-ABC/2.jpg","w":0,"h":0,"g":true},
              {"src":"https://shop.example/library/press/fratello.png","w":0,"h":0},
              {"src":"https://shop.example/library/long/1_mob.jpg","w":1200,"h":800}
            ]}
            """)
        #expect(d.imageURLs.map(\.lastPathComponent) == ["1.jpg", "2.jpg"])
    }

    @Test func aSecondSliderOfOtherPicturesIsLeftOut() throws {
        let d = try draft("""
            {"url":"https://shop.example/watch.html","images":[
              {"src":"https://shop.example/images/C63-XYZ/1.jpg","w":0,"h":0,"g":true},
              {"src":"https://shop.example/images/C63-XYZ/2.jpg","w":0,"h":0,"g":true},
              {"src":"https://shop.example/library/long-description/slide1.webp","w":0,"h":0,"g":true}
            ]}
            """)
        #expect(d.imageURLs.map(\.lastPathComponent) == ["1.jpg", "2.jpg"])
    }

    @Test func eachPictureInItsOwnFolderIsKept() throws {
        let d = try draft("""
            {"url":"https://brand.example/watch.html","metaImages":["https://brand.example/dam/Zi/Zi.png.transform.social.png"],"images":[
              {"src":"https://brand.example/dam/Iw/Iw.jpeg.transform.detail.jpeg","w":1280,"h":1600,"g":true},
              {"src":"https://brand.example/dam/hn/hn.jpeg.transform.detail.jpeg","w":1280,"h":1600,"g":true},
              {"src":"https://brand.example/dam/Iw/Iw.jpeg.transform.thumb.jpeg","w":200,"h":250,"g":true},
              {"src":"https://brand.example/dam/Zi/Zi.png.transform.thumb.png","w":201,"h":283,"g":true},
              {"src":"https://brand.example/dam/Zi/Zi.png.transform.detail.png","w":1280,"h":1810}
            ]}
            """)
        #expect(d.imageURLs.map(\.lastPathComponent) == ["Zi.png.transform.detail.png", "Iw.jpeg.transform.detail.jpeg", "hn.jpeg.transform.detail.jpeg"])
    }

    @Test func otherImagesNeedTheMainPhotosFolder() throws {
        let d = try draft("""
            {"url":"https://shop.example/watch.html","metaImages":["https://shop.example/images/C60-ABC/main.jpg"],"images":[
              {"src":"https://shop.example/library/banner.jpg","w":1600,"h":900},
              {"src":"https://shop.example/images/C60-ABC/side.jpg","w":800,"h":800}
            ]}
            """)
        #expect(d.imageURLs.map(\.lastPathComponent) == ["main.jpg", "side.jpg"])
    }

    @Test func commerceCloudImagesAreAskedForLarge() {
        let url = ImageURLNormalizer.normalize("https://shop.example/dw/image/v2/AB/on/demandware.static/x/1.jpg?sw=90&sh=90", relativeTo: nil)
        #expect(url?.query() == "sw=1600")
    }
}
